1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { parseFrontmatter } from './frontmatter';
4	import { renderMarkdown, renderPageHtml, renderIndexHtml } from './render';
5	import type { Page } from './types';
6	
7	export interface BuildOptions {
8	  contentDir: string;
9	  outputDir: string;
10	}
11	
12	export interface BuildResult {
13	  pages: Page[];
14	  outputDir: string;
15	}
16	
17	export function build(options: BuildOptions): BuildResult {
18	  const { contentDir, outputDir } = options;
19	
20	  if (!fs.existsSync(contentDir) || !fs.statSync(contentDir).isDirectory()) {
21	    throw new Error(`Content directory not found: ${contentDir}`);
22	  }
23	
24	  const markdownFiles = findMarkdownFiles(contentDir);
25	  const pages = markdownFiles.map((filePath) => buildPage(filePath, contentDir));
26	  pages.sort(comparePages);
27	
28	  fs.mkdirSync(outputDir, { recursive: true });
29	
30	  for (const page of pages) {
31	    const outPath = path.join(outputDir, page.outputFile);
32	    fs.mkdirSync(path.dirname(outPath), { recursive: true });
33	    fs.writeFileSync(outPath, renderPageHtml(page), 'utf8');
34	  }
35	
36	  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndexHtml(pages), 'utf8');
37	
38	  return { pages, outputDir };
39	}
