41	function comparePages(a: Page, b: Page): number {
42	  if (a.date && b.date) return b.date.localeCompare(a.date);
43	  if (a.date) return -1;
44	  if (b.date) return 1;
45	  return a.title.localeCompare(b.title);
46	}
47	
48	function findMarkdownFiles(dir: string): string[] {
49	  const entries = fs.readdirSync(dir, { withFileTypes: true });
50	  const files: string[] = [];
51	
52	  for (const entry of entries) {
53	    const fullPath = path.join(dir, entry.name);
54	    if (entry.isDirectory()) {
55	      files.push(...findMarkdownFiles(fullPath));
56	    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
57	      files.push(fullPath);
58	    }
59	  }
60	
61	  return files;
62	}
63	
64	function buildPage(filePath: string, contentDir: string): Page {
65	  const raw = fs.readFileSync(filePath, 'utf8');
66	  const { data, content } = parseFrontmatter(raw);
67	  const html = renderMarkdown(content);
68	
69	  const relativePath = path.relative(contentDir, filePath);
70	  const slug = slugify(relativePath);
71	  const title = typeof data.title === 'string' && data.title.trim() ? data.title : slug;
72	  const date = typeof data.date === 'string' && data.date.trim() ? data.date : undefined;
73	  const tags = Array.isArray(data.tags) ? data.tags.map(String) : [];
74	
75	  return {
76	    slug,
77	    title,
78	    date,
79	    tags,
80	    html,
81	    sourcePath: relativePath,
82	    outputFile: `${slug}.html`,
83	  };
84	}
85	
86	function slugify(relativePath: string): string {
87	  const withoutExt = relativePath.replace(/\.md$/i, '');
88	  const slug = withoutExt
89	    .split(path.sep)
90	    .join('-')
91	    .toLowerCase()
92	    .replace(/[^a-z0-9-]+/g, '-')
93	    .replace(/-+/g, '-')
94	    .replace(/^-|-$/g, '');
95	
96	  // "index" is reserved for the generated listing page.
97	  if (!slug || slug === 'index') return slug === 'index' ? 'index-page' : 'page';
98	  return slug;
99	}
